const input = $('Enquiry Input').first().json;
const gemini = $('Gemini Extract').first().json;

const rawText = String(
  input.Raw_Enquiry ??
  input.raw_text ??
  input.enquiry ??
  input.text ??
  ''
);

// Extract the actual Gemini response
const responseText =
  gemini.candidates?.[0]?.content?.parts?.[0]?.text;

if (!responseText) {
  throw new Error('Gemini returned no text content.');
}

let ai;
try {
  ai = JSON.parse(responseText);
} catch (e) {
  throw new Error('Gemini response was not valid JSON: ' + e.message);
}

const clean = (value) =>
  value === null || value === undefined || value === ''
    ? ''
    : value;

const missingFields = Array.isArray(ai.missing_fields)
  ? ai.missing_fields
  : [];

const humanReview =
  ai.human_review_required === true ||
  (Array.isArray(ai.conflicting_fields) &&
    ai.conflicting_fields.length > 0) ||
  (Array.isArray(ai.technical_concerns) &&
    ai.technical_concerns.length > 0);

const requiredDate = clean(ai.required_date);

const rec = {
  enquiry_id:
    input.enquiry_id ||
    input.Enquiry_ID ||
    input['Enquiry id'] ||
    'MPI-TEST-003',

  received_at: input.Received_At || new Date().toISOString(),
  source: input.source || input.Source || 'Website',
  raw_text: rawText,

  customer_name: clean(ai.customer_name),
  company_name: clean(ai.company_name),
  contact: clean(ai.contact),
  product_category: clean(ai.product_category),
  diameter_mm: ai.diameter_mm ?? '',
  height_mm: ai.height_mm ?? '',
  quantity: ai.quantity ?? '',
  application: clean(ai.application),

  // Keep the existing Google Sheets field name
  printing_required: clean(ai.printing_requirement),

  delivery_location: clean(ai.delivery_location),
  required_date: requiredDate,

  missing_fields: missingFields,
  conflicting_fields: Array.isArray(ai.conflicting_fields)
    ? ai.conflicting_fields
    : [],

  technical_concerns: Array.isArray(ai.technical_concerns)
    ? ai.technical_concerns
    : [],

  lead_status: missingFields.length > 0
    ? 'More information required'
    : 'Needs review',

  duplicate_of: '',
  human_review: humanReview ? 'Yes' : 'No',

  followup_draft:
    'DRAFT - NOT SENT. Human approval required.\n\n' +
    'Dear Customer,\n\n' +
    'Thank you for contacting Moti Packaging Industries.\n' +
    'We have recorded your enquiry for ' +
    (clean(ai.product_category) || 'packaging') + '.\n' +
    'Quantity: ' + (ai.quantity ?? 'Not provided') + '\n' +
    'Dimensions: ' + (ai.diameter_mm ?? 'Not provided') +
    ' mm diameter x ' + (ai.height_mm ?? 'Not provided') +
    ' mm height\n' +
    'Application: ' + (clean(ai.application) || 'Not provided') + '\n' +
    'Delivery location: ' +
    (clean(ai.delivery_location) || 'Not provided') + '\n\n' +
    (missingFields.length
      ? 'Please provide the following missing details: ' +
        missingFields.join(', ') + '.\n\n'
      : '') +
    'Our team will review the specifications before confirming a quotation.\n\n' +
    'Regards,\nMoti Packaging Industries',

  error: '',
  rules_pending: true,
  test_mode: true
};

return [{ json: rec }];

const rec = Object.assign({}, $('Validate AI Response').first().json);
const rows = $input.all().map(i => i.json);

function val(row, ...keys) {
  for (const key of keys) {
    if (row[key] !== undefined && row[key] !== null && row[key] !== '') {
      return row[key];
    }
  }
  return '';
}

function normContact(c) {
  if (!c) return '';
  const s = String(c).trim().toLowerCase();
  return s.includes('@') ? s : s.replace(/\D/g, '');
}

function same(a, b) {
  if (a === '' || a === null || a === undefined ||
      b === '' || b === null || b === undefined) return false;
  return String(a).trim().toLowerCase() === String(b).trim().toLowerCase();
}

const existing = rows.map(r => ({
  enquiry_id: val(r, 'Enquiry_ID', 'Enquiry id', 'enquiry_id'),
  contact: val(r, 'Contact', 'contact'),
  product_category: val(r, 'Product_Category', 'product_category'),
  diameter_mm: val(r, 'Diameter_mm', 'diameter_mm'),
  height_mm: val(r, 'Height_mm', 'height_mm'),
  quantity: val(r, 'Quantity', 'quantity'),
  delivery_location: val(r, 'Delivery_Location', 'delivery_location'),
  lead_status: val(r, 'Lead_Status', 'lead_status')
})).filter(r => r.enquiry_id);

const myContact = normContact(rec.contact);
const matches = [];

for (const r of existing) {
  // Same enquiry ID is the same record, not a duplicate of itself.
  if (String(r.enquiry_id) === String(rec.enquiry_id)) continue;

  const sameDims =
    same(r.diameter_mm, rec.diameter_mm) &&
    same(r.height_mm, rec.height_mm) &&
    same(r.quantity, rec.quantity);

  const sameContact =
    myContact !== '' && normContact(r.contact) === myContact;

  const sameSpec =
    sameDims &&
    same(r.product_category, rec.product_category) &&
    same(r.delivery_location, rec.delivery_location);

  if ((sameContact && sameDims) || sameSpec) {
    matches.push(String(r.enquiry_id));
  }
}

if (matches.length) {
  rec.duplicate_of = matches.join(', ');
  rec.lead_status = 'Possible duplicate enquiry';
  rec.human_review = 'Yes';
} else {
  rec.duplicate_of = '';
}

const labels = {
  customer_name: 'your name',
  contact: 'a contact phone number or email',
  product_category: 'the product type',
  diameter_mm: 'the diameter (mm)',
  height_mm: 'the height (mm)',
  quantity: 'the required quantity',
  delivery_location: 'the delivery location',
  required_date: 'the date you need delivery by'
};

if (rec.lead_status !== 'Processing failed') {
  const missing = Array.isArray(rec.missing_fields)
    ? rec.missing_fields
    : String(rec.missing_fields || '')
        .split(',').map(x => x.trim()).filter(Boolean);

  const lines = [
    'Dear ' + (rec.customer_name || 'Customer') + ',',
    '',
    'Thank you for your enquiry to Moti Packaging Industries.',
    'We have noted your requirements:'
  ];

  const facts = [
    ['Product', rec.product_category],
    ['Diameter', rec.diameter_mm != null ? rec.diameter_mm + ' mm' : null],
    ['Height', rec.height_mm != null ? rec.height_mm + ' mm' : null],
    ['Quantity', rec.quantity],
    ['Application', rec.application],
    ['Printing', rec.printing_requirement],
    ['Delivery location', rec.delivery_location],
    ['Required by', rec.required_date]
  ];

  for (const [label, value] of facts) {
    if (value !== null && value !== undefined && value !== '') {
      lines.push('- ' + label + ': ' + value);
    }
  }

  lines.push('');
  if (missing.length) {
    lines.push('To help our team prepare an accurate quotation, please share:');
    for (const field of missing) {
      lines.push('- ' + (labels[field] || field));
    }
  } else {
    lines.push('Our team will review your requirements and follow up.');
  }

  lines.push('', 'Regards,', 'Moti Packaging Industries');

  rec.followup_draft =
    'DRAFT - NOT SENT. Human approval required.\n\n' + lines.join('\n');
}

return [{ json: rec }];
